{
  "claim": "Purchased a $45 notebook for use during client meetings in Boston, receipt attached",
  "routing": "office_supplies",
  "category": "office_supplies",
  "rationale": "The item is a consumable under $50 and used for work, fitting the office_supplies category as defined in the policy."
}

{
  "claim": "Urgent firmware update for the team’s primary dev laptop — just got a notification it’s failing, need to buy new internal storage and SSD upgrade, receipt attached, cost $620, bought during a client project sprint.",
  "routing": "needs_finance",
  "category": "equipment",
  "rationale": "Any claim over $500 is routed to needs_finance"
}

{
  "claim": "Urgent! Just got a bottle of premium red for the client's birthday dinner — it’s not just wine, it’s a celebration, and the client actually said it was a big deal, so I’m sending it in now, no receipt attached, just a note from the client’s team.",
  "routing": "reject",
  "category": "client_entertainment",
  "rationale": "Alcohol-only purchases are rejected under the Meridian Consulting policy"
}

{
  "claim": "Got a free drink at the client’s office, no receipt, just said 'thanks' to the barista, and it was a fancy iced latte with caramel swirl — definitely not just a snack, more like a vibe check.",
  "routing": "client_entertainment",
  "category": "client_entertainment",
  "rationale": "A client was present and a hospitality-related drink was consumed, qualifying under client_entertainment per policy."
}

{
  "claim": "Just got a call from the Berlin office — they said I should buy a new monitor for my remote setup, and it's got a fancy 4K screen, so I'm goin' ahead and orderin' one with a receipt attached, like always.",
  "routing": "needs_manager",
  "category": "equipment",
  "rationale": "The claim is for equipment and falls within the $75 to $500 range with a receipt, triggering the needs_manager queue under the rule that anything from $75 up to $500 with a receipt goes to needs_manager."
}

{
  "claim": "Urgent need — team snack run at 3 PM, 5 of us grabbing burgers and fries, no receipt due to chaos in the backroom, all under 30 mins of actual work time, but we're all in the same office zone, so definitely a shared lunch situation.",
  "routing": "needs_manager",
  "category": "meals",
  "rationale": "meals claim involving 3 or more employees with no receipt falls under the needs_manager queue per policy rule."
}
